import { createHash } from "node:crypto";

/**
 * Session tokens generated by better-auth are 32 characters from [A-Za-z0-9].
 * We store a prefixed SHA-256 digest at rest. The prefix makes internal
 * better-auth flows that pass an already-hashed token back to the adapter
 * (refresh, revoke-other-sessions) deterministic, without making the stored
 * digest usable as an external credential: the HTTP cookie is signed by
 * better-auth before it reaches this adapter.
 */
export const SESSION_TOKEN_PREFIX = "v1:";
export const RAW_SESSION_TOKEN_RE = /^[A-Za-z0-9]{32}$/;

export function isHashedSessionToken(value: string): boolean {
  return value.startsWith(SESSION_TOKEN_PREFIX);
}

export function hashSessionToken(token: string): string {
  if (isHashedSessionToken(token)) return token;
  const digest = createHash("sha256").update(token, "utf8").digest("hex");
  return `${SESSION_TOKEN_PREFIX}${digest}`;
}

/** Constant-time-independent comparison helper for hashed invitation tokens. */
export function hashInvitationToken(token: string): string {
  return createHash("sha256").update(token, "utf8").digest("hex");
}
